507	#[cfg(test)]
508	mod tests {
509	    use super::*;
510	    use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
511	    use insta::assert_json_snapshot;
512	    use paigasus_helikon_core::{
513	        ContentPart, Item, ModelRequest, ResponseFormat, ToolChoice, ToolDef,
514	    };
515	    use serde_json::json;
516	
517	    use crate::capabilities::caps_for;
518	    use crate::family::ModelFamily;
519	    use crate::policy::{ForcedChoicePolicy, NativeNotice};
520	
521	    fn make_cfg(model_id: &str) -> Config {
522	        crate::builder::offline_config(model_id)
523	    }
524	
525	    /// A minimal Config for tests — uses a Claude model so synthesis works.
526	    fn claude_cfg() -> Config {
527	        make_cfg("anthropic.claude-3-5-sonnet-20241022-v2:0")
528	    }
529	
530	    /// A Llama config for testing unsupported-family degradation.
531	    fn llama_cfg() -> Config {
532	        make_cfg("meta.llama3-1-70b-instruct-v1:0")
533	    }
534	
535	    /// Build the request on the path that the policy of `cfg` selects.
536	    fn build(cfg: &Config, req: &ModelRequest) -> Result<PreparedConverse, ModelError> {
537	        build_request(
538	            cfg,
539	            req,
540	            ForcedChoicePolicy::new(&cfg.model_id, cfg.family).path(),
541	        )
542	    }
543	
544	    /// A model that rejects a forced tool choice (the native path).
545	    fn sonnet55_cfg() -> Config {
546	        make_cfg("global.anthropic.claude-sonnet-5-5")
547	    }
548	
549	    fn assert_no_forced_choice(p: &PreparedConverse) {
550	        assert!(
551	            !p.has_forced_tool_choice(),
552	            "forced tool choice on the native path"
553	        );
554	    }
555	
556	    fn user_text(s: &str) -> Item {
557	        Item::UserMessage {
558	            content: vec![ContentPart::Text { text: s.to_owned() }],
559	        }
560	    }
561	
562	    #[test]
563	    fn build_request_rejects_trailing_blank_user() {
564	        for tool_choice in [None, Some(ToolChoice::None)] {
565	            let mut req = ModelRequest::new();
566	            req.messages = vec![
567	                user_text("q"),
568	                Item::AssistantMessage {
569	                    content: vec![ContentPart::Text {
570	                        text: "a".to_owned(),
571	                    }],
572	                    agent: None,
573	                },
574	                user_text(""),
575	            ];
576	            if let Some(tc) = tool_choice {
577	                req.model_settings.tool_choice = Some(tc);
578	            }
579	            let err = build(&claude_cfg(), &req).unwrap_err();
580	            assert!(matches!(err, ModelError::Other(_)));
581	            assert!(
582	                err.to_string()
583	                    .contains("would end with an assistant message"),
584	                "{err}"
585	            );
586	        }
587	    }
588	
589	    #[test]
590	    fn empty_messages_returns_error() {
591	        let req = ModelRequest::new();
592	        let err = build(&claude_cfg(), &req).unwrap_err();
593	        assert!(matches!(err, ModelError::Other(_)));
594	    }
595	
596	    #[test]
597	    fn plain_text_turn_no_tools() {
598	        let mut req = ModelRequest::new();
599	        req.messages = vec![user_text("hello")];
600	        let p = build(&claude_cfg(), &req).unwrap();
601	        assert_eq!(p.model_id, "anthropic.claude-3-5-sonnet-20241022-v2:0");
602	        assert_eq!(p.messages.len(), 1);
603	        assert!(p.tool_config.is_none());
604	        assert!(!p.synthesizing);
605	    }
606	
607	    #[test]
608	    fn inference_config_fields_mapped() {
609	        let mut req = ModelRequest::new();
610	        req.messages = vec![user_text("hi")];
611	        req.model_settings.temperature = Some(0.7);
612	        req.model_settings.top_p = Some(0.9);
613	        req.model_settings.max_output_tokens = Some(512);
614	        let p = build(&claude_cfg(), &req).unwrap();
