                user_text(""),
            ];
            if let Some(tc) = tool_choice {
                req.model_settings.tool_choice = Some(tc);
            }
            let err = build(&claude_cfg(), &req).unwrap_err();
            assert!(matches!(err, ModelError::Other(_)));
            assert!(
                err.to_string()
                    .contains("would end with an assistant message"),
                "{err}"
            );
        }
    }

