1	//! `Vec<Item>` → Bedrock Converse `Message` / `SystemContentBlock` translation.
2	//!
3	//! Rules per SMA-329 spec §6 "Wire translation":
4	//! - `Item::System` → `SystemContentBlock::Text`; system blocks are never mixed
5	//!   into the `messages` slice.
6	//! - Blank text (empty or whitespace-only) is never sent: Converse rejects it.
7	//!   A dropped block leaves no placeholder. An `Item::System` with only blank
8	//!   text adds no system block.
9	//! - Adjacent same-role turns are joined into one turn.
10	//! - `Item::ToolCall` / `ContentPart::ToolUse` → `ContentBlock::ToolUse` on
11	//!   the assistant turn.
12	//! - `Item::ToolResult` queued pending → flushed as `ContentBlock::ToolResult`
13	//!   blocks prepended to the next user turn.
14	//! - No message with content after blank text is dropped → error.
15	
16	use aws_sdk_bedrockruntime::types::{
17	    ContentBlock, ConversationRole, Message, SystemContentBlock, ToolResultBlock,
18	    ToolResultContentBlock, ToolUseBlock,
19	};
20	use paigasus_helikon_core::{ContentPart, Item, ModelError};
21	#[cfg(test)]
22	use serde_json::{json, Value};
23	
24	use crate::document::value_to_document;
25	
26	/// Output of [`items_to_messages`].
27	#[derive(Debug)]
28	pub(crate) struct TranslatedMessages {
29	    /// System prompt blocks (`SystemContentBlock::Text`) extracted from
30	    /// `Item::System` entries.
31	    pub(crate) system: Vec<SystemContentBlock>,
32	    /// Conversation turns. Adjacent same-role turns are joined.
33	    pub(crate) messages: Vec<Message>,
34	}
35	
36	/// Translate the conversation into Bedrock Converse `Message`s.
37	///
38	/// Returns an error when no message with content remains. Empty or
39	/// whitespace-only text and unsupported parts are not sent. Also returns an
40	/// error when the last user message had only empty or whitespace-only text and
41	/// the request would then end with an assistant message.
42	pub(crate) fn items_to_messages(items: &[Item]) -> Result<TranslatedMessages, ModelError> {
43	    let mut system: Vec<SystemContentBlock> = Vec::new();
44	    let mut messages: Vec<Message> = Vec::new();
45	
46	    // Pending assistant-side content blocks (ToolUse / Text for an assistant turn
47	    // that hasn't been flushed yet).
48	    let mut pending_assistant: Vec<ContentBlock> = Vec::new();
49	    // Pending ToolResult blocks to prepend to the next user turn.
50	    let mut pending_tool_results: Vec<ContentBlock> = Vec::new();
51	    // `true` when the latest user message had blank text and produced no
52	    // block. Dropping it could leave the request ending with an assistant turn.
53	    let mut last_user_dropped = false;
54	
55	    /// Flush `pending_assistant` into an assistant Message on `messages`.
56	    ///
57	    /// If the last message is already an assistant turn, the pending content
58	    /// blocks are appended to it (coalescing) rather than creating a new turn.
59	    fn flush_assistant(messages: &mut Vec<Message>, pending: &mut Vec<ContentBlock>) {
60	        if !pending.is_empty() {
61	            let content = std::mem::take(pending);
62	            if messages
63	                .last()
64	                .map(|m| m.role == ConversationRole::Assistant)
65	                .unwrap_or(false)
66	            {
67	                // Coalesce: append to the existing assistant turn.
68	                let last = messages.last_mut().unwrap();
69	                last.content.extend(content);
70	            } else {
71	                let msg = Message::builder()
72	                    .role(ConversationRole::Assistant)
73	                    .set_content(Some(content))
74	                    .build()
75	                    .expect("role + non-empty content always valid");
76	                messages.push(msg);
77	            }
78	        }
79	    }
80	
81	    /// Flush `pending_tool_results` into a user Message on `messages`.
82	    ///
83	    /// If the last message is already a user turn, the results are appended to
84	    /// it (coalescing) rather than creating a new turn.
85	    fn flush_user_results(messages: &mut Vec<Message>, pending: &mut Vec<ContentBlock>) {
86	        if !pending.is_empty() {
87	            let content = std::mem::take(pending);
88	            if messages
89	                .last()
90	                .map(|m| m.role == ConversationRole::User)
91	                .unwrap_or(false)
92	            {
93	                let last = messages.last_mut().unwrap();
94	                last.content.extend(content);
95	            } else {
96	                let msg = Message::builder()
97	                    .role(ConversationRole::User)
98	                    .set_content(Some(content))
99	                    .build()
100	                    .expect("role + non-empty content always valid");
101	                messages.push(msg);
102	            }
103	        }
104	    }
105	
106	    for item in items {
107	        match item {
108	            Item::System { content } => {
109	                // System items are pulled out to the `system` slot; flush any
110	                // in-progress turns first so ordering is preserved.
111	                flush_assistant(&mut messages, &mut pending_assistant);
112	                flush_user_results(&mut messages, &mut pending_tool_results);
113	                let text = text_of(content);
114	                if !is_blank(&text) {
115	                    system.push(SystemContentBlock::Text(text));
116	                }
117	            }
118	
119	            Item::UserMessage { content } => {
120	                flush_assistant(&mut messages, &mut pending_assistant);
121	                // Pending tool results precede any user text in this turn.
122	                let mut blocks: Vec<ContentBlock> = std::mem::take(&mut pending_tool_results);
123	                let mut had_blank_text = false;
124	                for part in content {
125	                    match part {
126	                        ContentPart::Text { text } => {
127	                            if is_blank(text) {
128	                                had_blank_text = true;
129	                            } else {
130	                                blocks.push(ContentBlock::Text(text.clone()));
131	                            }
132	                        }
133	                        ContentPart::ToolResult { call_id, content } => {
134	                            // Native Anthropic-shaped ToolResult inside a UserMessage.
135	                            let result_block = build_tool_result_block(call_id, content);
136	                            blocks.push(ContentBlock::ToolResult(result_block));
137	                        }
138	                        // Provider data from another provider has no Bedrock form.
139	                        ContentPart::ProviderData { .. } => {}
140	                        _ => {
141	                            tracing::warn!(
142	                                target: "paigasus::bedrock::translate",
143	                                "unsupported ContentPart variant in UserMessage; skipping",
144	                            );
145	                        }
146	                    }
147	                }
148	                last_user_dropped = had_blank_text && blocks.is_empty();
149	                if !blocks.is_empty() {
150	                    if messages
151	                        .last()
152	                        .map(|m| m.role == ConversationRole::User)
153	                        .unwrap_or(false)
154	                    {
155	                        // Coalesce: append to the existing user turn.
156	                        let last = messages.last_mut().unwrap();
157	                        last.content.extend(blocks);
158	                    } else {
159	                        let msg = Message::builder()
160	                            .role(ConversationRole::User)
161	                            .set_content(Some(blocks))
162	                            .build()
163	                            .expect("role + non-empty content always valid");
164	                        messages.push(msg);
165	                    }
166	                }
167	            }
168	
169	            Item::AssistantMessage { content, .. } => {
170	                let mut blocks: Vec<ContentBlock> = Vec::new();
171	                for part in content {
172	                    match part {
173	                        ContentPart::Text { text } => {
174	                            if !is_blank(text) {
175	                                blocks.push(ContentBlock::Text(text.clone()));
176	                            }
177	                        }
178	                        ContentPart::ToolUse {
179	                            call_id,
180	                            name,
181	                            args,
182	                        } => {
183	                            let tool_use = ToolUseBlock::builder()
184	                                .tool_use_id(call_id)
185	                                .name(name)
186	                                .input(value_to_document(args))
187	                                .build()
188	                                .expect("tool_use_id + name + input always valid");
189	                            blocks.push(ContentBlock::ToolUse(tool_use));
190	                        }
191	                        ContentPart::Reasoning { .. } => {
192	                            tracing::warn!(
193	                                target: "paigasus::bedrock::translate",
194	                                "dropping ContentPart::Reasoning — round-trip not supported on Bedrock",
195	                            );
196	                        }
197	                        // Provider data from another provider has no Bedrock form.
198	                        ContentPart::ProviderData { .. } => {}
199	                        _ => {
200	                            tracing::warn!(
201	                                target: "paigasus::bedrock::translate",
202	                                "unsupported ContentPart variant in AssistantMessage; skipping",
203	                            );
204	                        }
205	                    }
206	                }
207	                // An assistant item with no blocks acts as if it were absent:
208	                // it flushes nothing, so an open tool round stays whole.
209	                //
210	                // A message made only of tool uses is the nested form of
211	                // `Item::ToolCall`. Inside an open round (results pending,
212	                // not all calls answered) it joins that round, as a call
213	                // does. A flush would put a user turn that lacks some
214	                // results right after the open assistant turn.
215	                if !blocks.is_empty()
216	                    && blocks.iter().all(|b| matches!(b, ContentBlock::ToolUse(_)))
217	                    && !pending_tool_results.is_empty()
218	                    && !round_is_answered(&messages, &pending_tool_results)
219	                {
220	                    last_user_dropped = false;
221	                    pending_assistant.extend(blocks);
222	                } else if !blocks.is_empty() {
223	                    last_user_dropped = false;
224	                    // Queued calls go first, then the results that answer them.
225	                    flush_assistant(&mut messages, &mut pending_assistant);
226	                    flush_user_results(&mut messages, &mut pending_tool_results);
227	                    if messages
228	                        .last()
229	                        .map(|m| m.role == ConversationRole::Assistant)
230	                        .unwrap_or(false)
231	                    {
232	                        // Coalesce: append to the existing assistant turn.
233	                        let last = messages.last_mut().unwrap();
234	                        last.content.extend(blocks);
235	                    } else {
236	                        let msg = Message::builder()
237	                            .role(ConversationRole::Assistant)
238	                            .set_content(Some(blocks))
239	                            .build()
240	                            .expect("role + non-empty content always valid");
241	                        messages.push(msg);
242	                    }
243	                }
244	            }
245	
246	            Item::ToolCall {
247	                call_id,
248	                name,
249	                args,
250	            } => {
251	                last_user_dropped = false;
252	                // A new call follows results already seen. Close that user
253	                // turn only when the last assistant round is fully answered;
254	                // otherwise the call joins that round.
255	                if !pending_tool_results.is_empty()
256	                    && round_is_answered(&messages, &pending_tool_results)
257	                {
258	                    flush_user_results(&mut messages, &mut pending_tool_results);
259	                }
260	                // Queue onto the pending assistant turn (flushed when a user
261	                // turn / system / end-of-input is encountered).
262	                let tool_use = ToolUseBlock::builder()
263	                    .tool_use_id(call_id)
264	                    .name(name)
265	                    .input(value_to_document(args))
266	                    .build()
267	                    .expect("tool_use_id + name + input always valid");
268	                pending_assistant.push(ContentBlock::ToolUse(tool_use));
269	            }
270	
271	            Item::ToolResult { call_id, content } => {
272	                last_user_dropped = false;
273	                // Flush the preceding assistant turn that requested this result.
274	                flush_assistant(&mut messages, &mut pending_assistant);
275	                // Queue onto pending user / tool-result turn.
276	                let result_block = build_tool_result_block(call_id, content);
277	                pending_tool_results.push(ContentBlock::ToolResult(result_block));
278	            }
279	
280	            _ => {
281	                tracing::warn!(
282	                    target: "paigasus::bedrock::translate",
283	                    "unknown Item variant; skipping",
284	                );
285	            }
286	        }
287	    }
288	
289	    // Flush any remaining pending content.
290	    flush_assistant(&mut messages, &mut pending_assistant);
291	    flush_user_results(&mut messages, &mut pending_tool_results);
292	
293	    // Guard: nothing to send.
294	    if messages.is_empty() {
295	        return Err(ModelError::Other(anyhow::anyhow!(
296	            "no message with content to send (empty or whitespace-only text and unsupported parts are not sent)"
297	        )));
298	    }
299	
300	    // Guard: a dropped blank user message must not leave the request ending
301	    // with an assistant turn. Converse would treat that as a prefill.
302	    if last_user_dropped
303	        && messages
304	            .last()
305	            .is_some_and(|m| m.role == ConversationRole::Assistant)
306	    {
307	        return Err(ModelError::Other(anyhow::anyhow!(
308	            "the last user message had only empty or whitespace-only text, which is not sent; the request would end with an assistant message"
309	        )));
310	    }
311	
312	    Ok(TranslatedMessages { system, messages })
313	}
