315	// ── Helpers ───────────────────────────────────────────────────────────────────
316	
317	/// `true` when `text` is empty or only whitespace. Converse rejects such blocks.
318	fn is_blank(text: &str) -> bool {
319	    text.trim().is_empty()
320	}
321	
322	/// `true` when every `ToolUse` id in the trailing run of assistant messages
323	/// has a matching `ToolResult` in `results`. Converse joins adjacent assistant
324	/// messages into one turn, so the whole run is one round. Also `true` when the
325	/// last message is not an assistant message, so the results then flush as
326	/// before.
327	fn round_is_answered(messages: &[Message], results: &[ContentBlock]) -> bool {
328	    messages
329	        .iter()
330	        .rev()
331	        .take_while(|m| m.role == ConversationRole::Assistant)
332	        .flat_map(|m| m.content.iter())
333	        .filter_map(|b| match b {
334	            ContentBlock::ToolUse(tu) => Some(tu.tool_use_id.as_str()),
335	            _ => None,
336	        })
337	        .all(|id| {
338	            results.iter().any(|r| match r {
339	                ContentBlock::ToolResult(tr) => tr.tool_use_id == id,
340	                _ => false,
341	            })
342	        })
343	}
344	
345	/// Extract and concatenate all text from a `Vec<ContentPart>`.
346	fn text_of(parts: &[ContentPart]) -> String {
347	    let mut s = String::new();
348	    for p in parts {
349	        if let ContentPart::Text { text } = p {
350	            if !s.is_empty() {
351	                s.push('\n');
352	            }
353	            s.push_str(text);
354	        }
355	    }
356	    s
357	}
358	
359	/// Build a `ToolResultBlock` from a call_id + content.
360	fn build_tool_result_block(call_id: &str, content: &[ContentPart]) -> ToolResultBlock {
361	    let text = text_of(content);
362	    ToolResultBlock::builder()
363	        .tool_use_id(call_id)
364	        .content(ToolResultContentBlock::Text(text))
365	        .build()
366	        .expect("tool_use_id + content always valid")
367	}
