369	// ── Wire-projection helper (for snapshot tests) ───────────────────────────────
370	
371	/// Project [`TranslatedMessages`] into a stable [`serde_json::Value`] for
372	/// snapshot tests. The projection is independent of SDK `Debug` output.
373	#[cfg(test)]
374	pub(crate) fn messages_to_wire_json(tm: &TranslatedMessages) -> Value {
375	    let system: Vec<Value> = tm
376	        .system
377	        .iter()
378	        .map(|s| match s {
379	            SystemContentBlock::Text(t) => json!({"type": "text", "text": t}),
380	            _ => json!({"type": "unknown"}),
381	        })
382	        .collect();
383	
384	    let messages: Vec<Value> = tm
385	        .messages
386	        .iter()
387	        .map(|m| {
388	            let role = match m.role {
389	                ConversationRole::User => "user",
390	                ConversationRole::Assistant => "assistant",
391	                _ => "unknown",
392	            };
393	            let content: Vec<Value> = m
394	                .content
395	                .iter()
396	                .map(|b| match b {
397	                    ContentBlock::Text(t) => json!({"type": "text", "text": t}),
398	                    ContentBlock::ToolUse(tu) => json!({
399	                        "type": "tool_use",
400	                        "toolUseId": tu.tool_use_id,
401	                        "name": tu.name,
402	                    }),
403	                    ContentBlock::ToolResult(tr) => {
404	                        let result_text = tr
405	                            .content
406	                            .iter()
407	                            .find_map(|c| {
408	                                if let ToolResultContentBlock::Text(t) = c {
409	                                    Some(t.as_str())
410	                                } else {
411	                                    None
412	                                }
413	                            })
414	                            .unwrap_or("");
415	                        json!({
416	                            "type": "tool_result",
417	                            "toolUseId": tr.tool_use_id,
418	                            "content": result_text,
419	                        })
420	                    }
421	                    _ => json!({"type": "unknown"}),
422	                })
423	                .collect();
424	            json!({"role": role, "content": content})
425	        })
426	        .collect();
427	
428	    json!({"system": system, "messages": messages})
429	}
