1	//! Map Amazon Bedrock SDK errors to [`paigasus_helikon_core::ModelError`].
2	//!
3	//! Per ADR-10 (*No silent auto-retry inside the loop*), the runner never
4	//! retries — retries are an application-layer concern via `RetryingModel`.
5	//!
6	//! One send fallback exists, and it is not a retry in the ADR-10 sense:
7	//! when an Anthropic model rejects a forced tool choice before the stream
8	//! starts, the provider sends one native request, which is a different request,
9	//! on the structured-output path. Four facts make this different from a retry.
10	//! The fallback sends a *different* request, not the same request again.
11	//! It occurs at most once for each request. It is logged. It never follows
12	//! a transient error (throttling, a 5xx error or a transport error).
13	//!
14	//! The match on the error text is a weak contract. If Bedrock changes the
15	//! text, the result is the same `ValidationException` as before this
16	//! fallback existed. The static model-id rule still sends the known models
17	//! on the native path from the first request.
18	//!
19	//! The `classify` function is a pure, unit-testable classifier that operates
20	//! on string error codes and optional HTTP status codes, mirroring the style
21	//! of the Anthropic provider's `map_error_type`. `map_sdk_error` wraps it
22	//! by extracting the code/status from the real [`SdkError`] variants.
23	
24	use aws_smithy_runtime_api::client::result::SdkError;
25	use aws_smithy_runtime_api::http::Headers;
26	use aws_smithy_types::error::metadata::ProvideErrorMetadata;
27	use paigasus_helikon_core::ModelError;
28	
29	/// Classify a Bedrock error into a [`ModelError`] from raw components.
30	///
31	/// This function is intentionally pure so it can be unit-tested without
32	/// constructing live `SdkError` values.
33	///
34	/// | `code`                       | Result                             |
35	/// |------------------------------|------------------------------------|
36	/// | `ThrottlingException`        | `RateLimited { retry_after_ms }`   |
37	/// | `ServiceUnavailableException`, `ModelNotReadyException`, `InternalServerException`, `ModelStreamErrorException`, `ModelTimeoutException` | `Unavailable` |
38	/// | `AccessDeniedException`      | `Refused { reason: message }`      |
39	/// | `ValidationException` + message contains "too long"/"maximum context" | `ContextLengthExceeded` |
40	/// | `ValidationException` (other)| `Other`                            |
41	/// | unknown / `None`             | `Other`                            |
42	pub(crate) fn classify(
43	    code: Option<&str>,
44	    _status: Option<u16>,
45	    message: &str,
46	    retry_after_ms: Option<u64>,
47	) -> ModelError {
48	    match code {
49	        Some("ThrottlingException") => ModelError::RateLimited { retry_after_ms },
50	        Some(
51	            "ServiceUnavailableException"
52	            | "ModelNotReadyException"
53	            | "InternalServerException"
54	            | "ModelStreamErrorException"
55	            | "ModelTimeoutException",
56	        ) => ModelError::Unavailable,
57	        Some("AccessDeniedException") => ModelError::Refused {
58	            reason: message.to_owned(),
59	        },
60	        Some("ValidationException") => {
61	            let msg_lower = message.to_ascii_lowercase();
62	            if msg_lower.contains("too long") || msg_lower.contains("maximum context") {
63	                ModelError::ContextLengthExceeded
64	            } else {
65	                ModelError::Other(anyhow::anyhow!("bedrock ValidationException: {message}"))
66	            }
67	        }
68	        _ => ModelError::Other(anyhow::anyhow!(
69	            "bedrock error {}: {message}",
70	            code.unwrap_or("unknown")
71	        )),
72	    }
73	}
74	
75	/// Returns `true` when a Bedrock error says that the model rejects a forced
76	/// tool choice (`toolChoice` `any` or `tool`).
77	///
78	/// The match is on the error code and on two exact texts: the text from the
79	/// model layer and the text from the Bedrock layer.
80	pub(crate) fn is_forced_choice_rejection(code: Option<&str>, message: &str) -> bool {
81	    code == Some("ValidationException")
82	        && (message.contains(r#"type "tool" and "any" are not supported"#)
83	            || message.contains("doesn't support the toolConfig.toolChoice."))
84	}
85	
86	/// A failed send, with the flag that the fallback reads.
87	#[derive(Debug)]
88	pub(crate) struct SendFailure {
89	    /// `true` when the service rejected a forced tool choice.
90	    pub(crate) forced_choice_rejected: bool,
91	    /// The mapped error that goes to the caller when no fallback occurs.
92	    pub(crate) error: ModelError,
93	}
94	
95	/// Parse the `Retry-After` header (integer seconds) from Bedrock response headers into milliseconds.
96	///
97	/// Returns `None` when the header is absent or its value is not a non-negative integer
98	/// (HTTP-date retry-after values are not supported — `None` is the safe fallback).
99	pub(crate) fn parse_retry_after_ms(headers: &Headers) -> Option<u64> {
100	    headers
101	        .get("retry-after")
102	        .and_then(|v| v.trim().parse::<u64>().ok())
103	        .map(|seconds| seconds.saturating_mul(1000))
104	}
105	
106	/// Map a Bedrock SDK [`SdkError`] to a [`ModelError`].
107	///
108	/// For `ServiceError`, the modeled error code and message are extracted via
109	/// [`ProvideErrorMetadata`] and delegated to [`classify`]. Transport-level
110	/// failures (`DispatchFailure`, `TimeoutError`, `ConstructionFailure`,
111	/// `ResponseError`) map to [`ModelError::Transport`].
112	///
113	/// This generic variant does **not** inspect HTTP headers (the response type `R`
114	/// may not be an HTTP response — e.g. the event-stream `recv()` path produces
115	/// `SdkError<_, RawMessage>`). Call [`map_sdk_http_error`] when `R` is known to
116	/// be [`aws_smithy_runtime_api::http::Response`] and you want `Retry-After`
117	/// header extraction.
118	pub(crate) fn map_sdk_error<E, R>(err: SdkError<E, R>) -> ModelError
119	where
120	    E: ProvideErrorMetadata + std::fmt::Debug,
121	    R: std::fmt::Debug,
122	{
123	    match &err {
124	        SdkError::ServiceError(svc) => {
125	            let code = svc.err().code();
126	            let message = svc.err().message().unwrap_or("");
127	            classify(code, None, message, None)
128	        }
129	        SdkError::DispatchFailure(_)
130	        | SdkError::TimeoutError(_)
131	        | SdkError::ConstructionFailure(_)
132	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
133	        // Non-exhaustive: treat any future variant as transport.
134	        _ => ModelError::Transport(format!("{err:?}")),
135	    }
136	}
137	
138	/// Map a Bedrock SDK [`SdkError`] whose response type is the concrete HTTP
139	/// response to a [`ModelError`], extracting `Retry-After` header and HTTP
140	/// status from the raw response.
141	///
142	/// This is the preferred variant for the initial `fluent.send()` call on a
143	/// Bedrock operation, where the SDK returns
144	/// `SdkError<E, aws_smithy_runtime_api::client::orchestrator::HttpResponse>`.
145	pub(crate) fn map_sdk_http_error<E>(
146	    err: SdkError<E, aws_smithy_runtime_api::http::Response>,
147	) -> ModelError
148	where
149	    E: ProvideErrorMetadata + std::fmt::Debug,
150	{
151	    match &err {
152	        SdkError::ServiceError(svc) => {
153	            let code = svc.err().code();
154	            let message = svc.err().message().unwrap_or("");
155	            let raw = svc.raw();
156	            let status = Some(raw.status().as_u16());
157	            let retry_after_ms = parse_retry_after_ms(raw.headers());
158	            classify(code, status, message, retry_after_ms)
159	        }
160	        SdkError::DispatchFailure(_)
161	        | SdkError::TimeoutError(_)
162	        | SdkError::ConstructionFailure(_)
163	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
164	        // Non-exhaustive: treat any future variant as transport.
165	        _ => ModelError::Transport(format!("{err:?}")),
166	    }
167	}
168	
169	/// Map a failed send to a [`SendFailure`].
170	///
171	/// The raw code and message of a `ServiceError` are read before the error is
172	/// mapped by [`map_sdk_http_error`]. All other variants are not a rejection
173	/// of a forced tool choice.
174	pub(crate) fn send_failure<E>(
175	    err: SdkError<E, aws_smithy_runtime_api::http::Response>,
176	) -> SendFailure
177	where
178	    E: ProvideErrorMetadata + std::fmt::Debug,
179	{
180	    let forced_choice_rejected = match &err {
181	        SdkError::ServiceError(svc) => {
182	            is_forced_choice_rejection(svc.err().code(), svc.err().message().unwrap_or(""))
183	        }
184	        _ => false,
185	    };
186	    SendFailure {
187	        forced_choice_rejected,
188	        error: map_sdk_http_error(err),
189	    }
190	}
