414	            aws_smithy_runtime_api::http::StatusCode::try_from(status).expect("status"),
415	            aws_smithy_types::body::SdkBody::empty(),
416	        );
417	        SdkError::service_error(meta, raw)
418	    }
419	
420	    #[test]
421	    fn send_failure_flags_a_forced_choice_rejection() {
422	        let f = send_failure(service_error("ValidationException", BEDROCK_LAYER, 400));
423	        assert!(f.forced_choice_rejected);
424	        assert!(matches!(f.error, ModelError::Other(_)));
425	    }
426	
427	    #[test]
428	    fn send_failure_keeps_other_errors_unflagged() {
429	        let f = send_failure(service_error("ThrottlingException", "slow down", 429));
430	        assert!(!f.forced_choice_rejected);
431	        assert!(matches!(f.error, ModelError::RateLimited { .. }));
432	        let f = send_failure(service_error(
433	            "ValidationException",
434	            "Input is too long for requested model.",
435	            400,
436	        ));
437	        assert!(!f.forced_choice_rejected);
438	        assert!(matches!(f.error, ModelError::ContextLengthExceeded));
439	    }
