309	    use futures_core::Stream;
310	    use futures_util::StreamExt;
311	
312	    /// Build a stream that yields `n` `TokenDelta` events then ends.
313	    fn token_stream(
314	        n: usize,
315	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
316	        let events: Vec<Result<ModelEvent, ModelError>> = (0..n)
317	            .map(|i| {
318	                Ok(ModelEvent::TokenDelta {
319	                    text: format!("chunk-{i}"),
320	                })
321	            })
322	            .collect();
323	        futures_util::stream::iter(events)
324	    }
325	
326	    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
327	    fn token_stream_with_finish(
328	        n: usize,
329	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
330	        use paigasus_helikon_core::FinishReason;
331	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
332	            .map(|i| {
333	                Ok(ModelEvent::TokenDelta {
334	                    text: format!("chunk-{i}"),
335	                })
336	            })
337	            .collect();
338	        events.push(Ok(ModelEvent::Finish {
339	            reason: FinishReason::Stop,
340	        }));
341	        futures_util::stream::iter(events)
342	    }
343	
344	    #[tokio::test]
345	    async fn cancel_before_stream_ends_no_finish() {
346	        let cancel = CancellationToken::new();
347	        let source = token_stream(10);
348	
349	        // Cancel immediately — the stream should yield 0 events and no Finish.
350	        cancel.cancel();
351	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
352	
353	        let has_finish = events
354	            .iter()
355	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
356	        assert!(!has_finish, "cancelled stream must not emit Finish");
357	    }
358	
359	    #[tokio::test]
360	    async fn cancel_mid_stream_no_finish() {
361	        use std::sync::atomic::{AtomicBool, Ordering};
362	        use std::sync::Arc;
363	
364	        let cancel = CancellationToken::new();
365	        let cancel_clone = cancel.clone();
366	
367	        // A stream that cancels itself after yielding the first token.
368	        let cancelled = Arc::new(AtomicBool::new(false));
369	        let cancelled_clone = cancelled.clone();
370	
371	        let source = async_stream::stream! {
372	            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
373	            // Signal cancellation after the first token.
374	            if !cancelled_clone.swap(true, Ordering::SeqCst) {
375	                cancel_clone.cancel();
376	            }
377	            // `biased;` in drive_stream_with_token's tokio::select! checks the
378	            // cancel arm first on every iteration, so once cancel() fires the
379	            // driver exits before polling the source again — making this
380	            // single-threaded ordering deterministic and guaranteeing no Finish
381	            // is emitted after cancel.
382	            yield Ok(ModelEvent::TokenDelta { text: "second".to_owned() });
383	            yield Ok(ModelEvent::Finish { reason: paigasus_helikon_core::FinishReason::Stop });
384	        };
385	
386	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
387	
388	        let has_finish = events
389	            .iter()
390	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
391	        assert!(!has_finish, "mid-stream cancel must not emit Finish");
392	    }
393	
394	    #[tokio::test]
395	    async fn uncancelled_stream_emits_finish() {
396	        let cancel = CancellationToken::new();
397	        let source = token_stream_with_finish(3);
398	
399	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
400	
401	        let has_finish = events
402	            .iter()
403	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
404	        assert!(has_finish, "uncancelled stream must emit Finish");
405	        // All 3 token deltas + finish = 4 events.
406	        assert_eq!(events.len(), 4, "expected 3 tokens + 1 finish");
407	    }
408	
409	    #[tokio::test]
410	    async fn cancel_does_not_drop_events_already_yielded() {
411	        let cancel = CancellationToken::new();
412	        // 5 events, no finish.  Don't cancel — all should arrive.
413	        let source = token_stream(5);
414	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
415	        assert_eq!(events.len(), 5, "all events must arrive when not cancelled");
416	    }
