1	//! `StreamTranslator` — Bedrock `ConverseStreamOutput` events → `ModelEvent`.
2	//!
3	//! ## Usage / Finish ordering
4	//!
5	//! The Bedrock Converse API emits events in this order:
6	//!
7	//! ```text
8	//! MessageStart
9	//! ContentBlockStart | ContentBlockDelta | ContentBlockStop  (interleaved)
10	//! MessageStop         ← stop_reason lives here
11	//! Metadata            ← usage lives here (AFTER MessageStop)
12	//! ```
13	//!
14	//! Per the `paigasus_helikon_core::Model::invoke` ordering contract,
15	//! `ModelEvent::Finish` is terminal and `ModelEvent::Usage` may appear
16	//! anywhere in the stream — most providers emit one immediately before
17	//! `Finish`. Because Bedrock emits `Metadata` (where usage lives) **after**
18	//! `MessageStop` (where the stop reason lives), this translator buffers the
19	//! stop reason when `MessageStop` arrives and emits nothing until `Metadata`
20	//! arrives — at that point it emits `Usage` immediately followed by `Finish`.
21	//!
22	//! If (contrary to the typical wire order) `Metadata` arrives **before**
23	//! `MessageStop`, `Usage` is emitted immediately on `Metadata` and `Finish`
24	//! is emitted immediately on `MessageStop`, which also satisfies the contract.
25	
26	use std::collections::HashMap;
27	
28	use aws_sdk_bedrockruntime::types::{
29	    ContentBlockDelta, ContentBlockStart, ConverseStreamOutput, ReasoningContentBlockDelta,
30	    StopReason,
31	};
32	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
33	
34	use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
35	
36	// ── internal block state ──────────────────────────────────────────────────────
37	
38	/// Per-content-block state keyed by `content_block_index`.
39	///
40	/// Reasoning content blocks are identified purely by the
41	/// `ContentBlockDelta::ReasoningContent` delta variant; no separate block-state
42	/// entry is needed for them.
43	#[derive(Debug)]
44	enum BlockState {
45	    Text,
46	    ToolUse {
47	        call_id: String,
48	        name: String,
49	        /// `true` after the first `ToolCallDelta` has been emitted (name
50	        /// appears only in that first delta; subsequent deltas set it to
51	        /// `None`).
52	        name_emitted: bool,
53	    },
54	}
55	
56	// ── public translator ─────────────────────────────────────────────────────────
57	
58	/// State machine that maps Bedrock `ConverseStreamOutput` events to
59	/// `paigasus_helikon_core::ModelEvent`s.
60	///
61	/// Call [`StreamTranslator::consume`] once per SDK event.  The translator is
62	/// pure (no I/O) and is intended to be driven from an `async_stream!` wrapper
63	/// that feeds it chunks from `converse_stream`.
64	///
65	/// ## Synthesizing mode
66	///
67	/// When `synthesizing = true` the model was asked to fill a JSON schema via a
68	/// forced-tool call (`__paigasus_structured_output__`).  In that mode the
69	/// synthesized tool's input deltas are re-emitted as `TokenDelta`s and the
70	/// terminal `tool_use` stop reason is rewritten to `Stop`.  If a *real* tool
71	/// fires alongside the synthesized one, `ModelError::Other` is returned
72	/// (protocol violation).
73	#[derive(Debug, Default)]
74	pub struct StreamTranslator {
75	    /// `content_block_index` → per-block state.
76	    blocks: HashMap<i32, BlockState>,
77	    /// Whether we are in structured-output synthesis mode.
78	    synthesizing: bool,
79	    /// Whether the request used native structured output (`outputConfig`).
80	    native: bool,
81	    /// The content-block index of the synthesized tool's block (if any).
82	    synthesized_block_index: Option<i32>,
83	    /// `true` if at least one *real* (non-synthesized) tool block started.
84	    real_tool_fired: bool,
85	    /// Buffered stop reason from `MessageStop`; held until `Metadata` arrives
86	    /// so that `Usage` can be emitted first.
87	    pending_stop_reason: Option<StopReason>,
88	    /// `true` once a `Metadata` event has been processed.
89	    metadata_seen: bool,
90	}
91	
92	impl StreamTranslator {
93	    /// Create a new translator.
94	    ///
95	    /// Set `synthesizing` to `true` when the request was built with
96	    /// structured-output synthesis (forced `__paigasus_structured_output__`
97	    /// tool call).
98	    pub fn new(synthesizing: bool) -> Self {
99	        Self {
100	            synthesizing,
101	            ..Default::default()
102	        }
103	    }
104	
105	    /// Tell the translator that the request used native structured output.
106	    /// An anchor call then logs one warning, because `outputConfig` did not
107	    /// constrain the text that the anchor carries.
108	    pub(crate) fn native(mut self, native: bool) -> Self {
109	        self.native = native;
110	        self
111	    }
112	
113	    /// Consume one `ConverseStreamOutput` event and return zero or more
114	    /// `ModelEvent`s (or `ModelError`s) produced by it.
115	    pub fn consume(&mut self, ev: ConverseStreamOutput) -> Vec<Result<ModelEvent, ModelError>> {
116	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
117	
118	        match ev {
119	            // ── events that produce no output ─────────────────────────────────
120	            ConverseStreamOutput::MessageStart(_) => {}
121	            ConverseStreamOutput::ContentBlockStop(_) => {}
122	
123	            // ── content block start ───────────────────────────────────────────
124	            ConverseStreamOutput::ContentBlockStart(e) => {
125	                let idx = e.content_block_index();
126	                match e.start() {
127	                    Some(ContentBlockStart::ToolUse(tu)) => {
128	                        let call_id = tu.tool_use_id().to_owned();
129	                        let name = tu.name().to_owned();
130	
131	                        if self.synthesizing && name == SYNTHESIZED_TOOL_NAME {
132	                            if self.native && self.synthesized_block_index.is_none() {
133	                                tracing::warn!(
134	                                    target: "paigasus::bedrock::stream",
135	                                    "the model called the structured-output anchor on the native path; outputConfig did not constrain this text"
136	                                );
137	                            }
138	                            self.synthesized_block_index = Some(idx);
139	                        } else {
140	                            self.real_tool_fired = true;
141	                            // Emit the name-carrying delta immediately on block
142	                            // start (mirrors the Anthropic provider's behaviour
143	                            // of emitting name on the first input-json delta).
144	                            // We *don't* emit here — we wait for the first
145	                            // tool-input delta so the call_id→state map is
146	                            // consistent.
147	                        }
148	                        self.blocks.insert(
149	                            idx,
150	                            BlockState::ToolUse {
151	                                call_id,
152	                                name,
153	                                name_emitted: false,
154	                            },
155	                        );
156	                    }
157	                    Some(ContentBlockStart::Image(_) | ContentBlockStart::ToolResult(_)) => {
158	                        // Not a tool we translate; record nothing.
159	                    }
160	                    Some(_) | None => {
161	                        // Text or unknown start: record as text block.
162	                        self.blocks.insert(idx, BlockState::Text);
163	                    }
164	                }
165	            }
166	
167	            // ── content block delta ───────────────────────────────────────────
168	            ConverseStreamOutput::ContentBlockDelta(e) => {
169	                let idx = e.content_block_index();
170	                match e.delta() {
171	                    Some(ContentBlockDelta::Text(text)) => {
172	                        out.push(Ok(ModelEvent::TokenDelta { text: text.clone() }));
173	                    }
174	                    Some(ContentBlockDelta::ToolUse(tu_delta)) => {
175	                        let input = tu_delta.input().to_owned();
176	                        let is_synth = Some(idx) == self.synthesized_block_index;
177	
178	                        if is_synth {
179	                            // Remap synthesized tool input to TokenDelta.
180	                            out.push(Ok(ModelEvent::TokenDelta { text: input }));
181	                        } else if let Some(BlockState::ToolUse {
182	                            call_id,
183	                            name,
184	                            name_emitted,
185	                        }) = self.blocks.get_mut(&idx)
186	                        {
187	                            let emit_name = if *name_emitted {
188	                                None
189	                            } else {
190	                                *name_emitted = true;
191	                                Some(name.clone())
192	                            };
193	                            out.push(Ok(ModelEvent::ToolCallDelta {
194	                                call_id: call_id.clone(),
195	                                name: emit_name,
196	                                args_delta: input,
197	                            }));
198	                        }
199	                        // If no block state (shouldn't happen for well-formed
200	                        // streams), silently drop rather than panic.
201	                    }
202	                    Some(ContentBlockDelta::ReasoningContent(rc)) => match rc {
203	                        ReasoningContentBlockDelta::Text(text) => {
204	                            out.push(Ok(ModelEvent::ReasoningDelta { text: text.clone() }));
205	                        }
206	                        ReasoningContentBlockDelta::Signature(_) => {
207	                            // Signature is a round-trip token for multi-turn
208	                            // extended-thinking; we drop it here (not yet
209	                            // plumbed through the session layer).
210	                            tracing::debug!(
211	                                target: "paigasus::bedrock::stream",
212	                                "reasoning signature delta dropped (round-trip not yet supported)",
213	                            );
214	                        }
215	                        ReasoningContentBlockDelta::RedactedContent(_) => {
216	                            // Encrypted reasoning blob — provider-opaque, drop.
217	                            tracing::debug!(
218	                                target: "paigasus::bedrock::stream",
219	                                "reasoning redacted-content delta dropped",
220	                            );
221	                        }
222	                        _ => {
223	                            // Forward-compat: ignore unknown reasoning variants.
224	                        }
225	                    },
226	                    // Image, ToolResult, Citation, Unknown deltas — drop.
227	                    Some(_) | None => {}
228	                }
229	            }
230	
231	            // ── message stop (stop_reason) ────────────────────────────────────
232	            ConverseStreamOutput::MessageStop(e) => {
233	                let stop_reason = e.stop_reason().clone();
234	                if self.metadata_seen {
235	                    // Metadata already arrived; emit Finish now.
236	                    out.extend(self.finish_events(stop_reason));
237	                } else {
238	                    // Buffer; Metadata will trigger Usage + Finish.
239	                    self.pending_stop_reason = Some(stop_reason);
240	                }
241	            }
242	
243	            // ── metadata (usage) ──────────────────────────────────────────────
244	            ConverseStreamOutput::Metadata(e) => {
245	                self.metadata_seen = true;
246	                if let Some(usage) = e.usage() {
247	                    out.push(Ok(ModelEvent::Usage {
248	                        input_tokens: usage.input_tokens().max(0) as u32,
249	                        output_tokens: usage.output_tokens().max(0) as u32,
250	                        cached_input_tokens: usage
251	                            .cache_read_input_tokens()
252	                            .map(|n| n.max(0) as u32),
253	                        reasoning_tokens: None,
254	                    }));
255	                }
256	                // If a buffered stop reason is waiting, emit Finish now.
257	                if let Some(reason) = self.pending_stop_reason.take() {
258	                    out.extend(self.finish_events(reason));
259	                }
260	            }
261	
262	            // Forward-compat catch-all: Unknown and any future enum variants
263	            // added by the SDK are silently ignored.
264	            _ => {}
265	        }
266	
267	        out
268	    }
269	
270	    /// Flush any buffered stop reason when the Bedrock stream ends normally
271	    /// (EOF) without having emitted a `Metadata` event.
272	    ///
273	    /// Returns the terminal `Finish` event (or a `ModelError::Other` for the
274	    /// both-tools-fired error condition) if a stop reason is still pending,
275	    /// or `None` if the stream already emitted its terminal event through the
276	    /// normal `Metadata`→`Finish` path.
277	    ///
278	    /// **Call this only on the EOF path, not on the cancellation path.**
279	    /// Cancellation must end the stream without emitting `Finish`.
280	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
281	        self.pending_stop_reason
282	            .take()
283	            .map(|reason| self.finish_events(reason).remove(0))
284	    }
285	
286	    // ── private helpers ───────────────────────────────────────────────────────
287	
288	    /// Translate a `StopReason` into the terminal event(s).
289	    ///
290	    /// Returns a single `Ok(Finish{..})` in normal cases, or a single
291	    /// `Err(ModelError::Other)` when both a real and the synthesized tool
292	    /// fired in synthesis mode.
293	    fn finish_events(&self, reason: StopReason) -> Vec<Result<ModelEvent, ModelError>> {
294	        let finish = match reason {
295	            StopReason::EndTurn | StopReason::StopSequence => Ok(ModelEvent::Finish {
296	                reason: FinishReason::Stop,
297	            }),
298	            StopReason::ToolUse => {
299	                if self.synthesizing {
300	                    if self.real_tool_fired {
301	                        // Both tools fired — protocol violation.
302	                        Err(ModelError::Other(anyhow::anyhow!(
303	                            "bedrock stream: structured-output synthesis: \
304	                             model fired both a real tool and the synthesized \
305	                             output tool '__paigasus_structured_output__'"
306	                        )))
307	                    } else {
308	                        // Only synthesized tool fired — rewrite to Stop.
309	                        Ok(ModelEvent::Finish {
310	                            reason: FinishReason::Stop,
311	                        })
312	                    }
313	                } else {
314	                    Ok(ModelEvent::Finish {
315	                        reason: FinishReason::ToolCalls,
316	                    })
317	                }
318	            }
319	            StopReason::MaxTokens => Ok(ModelEvent::Finish {
320	                reason: FinishReason::Length,
321	            }),
322	            StopReason::GuardrailIntervened | StopReason::ContentFiltered => {
323	                Ok(ModelEvent::Finish {
324	                    reason: FinishReason::ContentFilter,
325	                })
326	            }
327	            other => Ok(ModelEvent::Finish {
328	                reason: FinishReason::Other(other.as_str().to_owned()),
329	            }),
330	        };
331	        vec![finish]
332	    }
333	}
