    fn u64_above_i64_max_stays_posint() {
        use aws_smithy_types::Number;
        let big = json!(u64::MAX);
        assert!(
            matches!(value_to_document(&big), Document::Number(Number::PosInt(n)) if n == u64::MAX)
        );
    }

