1	//! Document-block helpers for the Bedrock Converse API.
2	//!
3	//! The [`aws_smithy_types::Document`] type is a recursive JSON-like value
4	//! enum used as the `input` field in Bedrock `ToolUseBlock`s. This module
5	//! provides a converter from [`serde_json::Value`].
6	//!
7	//! Note: `arbitrary_precision` is **not** enabled in this workspace. All
8	//! number conversion goes through the `as_u64`/`as_i64`/`as_f64` accessors.
9	
10	use aws_smithy_types::{Document, Number};
11	use serde_json::Value;
12	use std::collections::HashMap;
13	
14	/// Convert a [`serde_json::Value`] into an [`aws_smithy_types::Document`].
15	///
16	/// Numbers follow the precision available without `arbitrary_precision`:
17	/// - Unsigned integers use [`Number::PosInt`].
18	/// - Signed negative integers use [`Number::NegInt`].
19	/// - Floating-point numbers use [`Number::Float`].
20	pub(crate) fn value_to_document(v: &Value) -> Document {
21	    match v {
22	        Value::Null => Document::Null,
23	        Value::Bool(b) => Document::Bool(*b),
24	        Value::String(s) => Document::String(s.clone()),
25	        Value::Number(n) => {
26	            if let Some(u) = n.as_u64() {
27	                Document::Number(Number::PosInt(u))
28	            } else if let Some(i) = n.as_i64() {
29	                Document::Number(Number::NegInt(i))
30	            } else {
31	                // Falls through to f64; as_f64() is always Some when
32	                // arbitrary_precision is disabled and the value is finite.
33	                Document::Number(Number::Float(n.as_f64().unwrap_or(0.0)))
34	            }
35	        }
36	        Value::Array(arr) => Document::Array(arr.iter().map(value_to_document).collect()),
37	        Value::Object(map) => {
38	            let mut out: HashMap<String, Document> = HashMap::with_capacity(map.len());
39	            for (k, v) in map {
40	                out.insert(k.clone(), value_to_document(v));
41	            }
42	            Document::Object(out)
43	        }
44	    }
45	}
